{
  "title": "Hidden Corners and Quiet Wonders",
  "summary": "A slower day in Cusco that swaps the busy salt flats for the unexpected calm of San Blas and a gentle walk through the Moray terraces, with time to linger over meals.",
  "stops": [
    {
      "poi_id": "p2",
      "kind": "activity",
      "must_do_id": "m2",
      "note": "We keep the Qorikancha, of course. The crew asked for history, and this temple holds more of it than most places in the city.",
      "must_do_id": "m2"
    },
    {
      "poi_id": "p6",
      "kind": "activity",
      "must_do_id": null,
      "note": "A surprise for the market and photo lovers: San Blas is a little maze of workshops and balconies that most visitors rush past.",
      "must_do_id": null
    },
    {
      "poi_id": "p19",
      "kind": "meal",
      "must_do_id": null,
      "note": "Lunch at Morena Peruvian Kitchen, where the vegetarian options are as warm as the welcome.",
      "must_do_id": null
    },
    {
      "poi_id": "p11",
      "kind": "activity",
      "must_do_id": null,
      "note": "Moray is the unexpected twist: a short ride to the terraces, where the afternoon light makes the rings look like a giant green amphitheatre.",
      "must_do_id": null
    },
    {
      "poi_id": "p18",
      "kind": "meal",
      "must_do_id": null,
      "note": "Dinner at La Bodega 138, a simple place with honest vegetarian plates and a quiet corner to rest after the ride back.",
      "must_do_id": null
    }
  ]
}
